SELECT ?ps ?printTime_s (GROUP_CONCAT(DISTINCT ?qn; separator=", ") AS ?recommendedFor) WHERE {
  ?ps a f:ParameterSetting ; f:estimatedPrintTimeValue ?printTime_s .
  OPTIONAL { ?ps f:recommendsSettingFor ?q . BIND(STRAFTER(STR(?q), "#") AS ?qn) }
} GROUP BY ?ps ?printTime_s ORDER BY ?ps

SELECT ?ps ?worstMargin ?char ?specimen ?value ?limit WHERE {
 { SELECT ?ps (MIN(?m) AS ?worstMargin) WHERE {
  ?e a f:NotRecommendedSetting .

  ?e f:evaluatesSetting ?ps ; f:forRequirement f:Req02 ; f:coversAssessment ?a .
  ?a f:assessesResult ?r .
  ?sp f:hasResult ?r .
  { f:Req02 f:requiredMaxLengthDeviation ?lim . ?r f:absLengthDeviationValue ?v . BIND("length" AS ?char) }
  UNION { f:Req02 f:requiredMaxWidthDeviation ?lim . ?r f:absWidthDeviationValue ?v . BIND("width" AS ?char) }
  UNION { f:Req02 f:requiredMaxHeightDeviation ?lim . ?r f:absHeightDeviationValue ?v . BIND("height" AS ?char) }
  UNION { f:Req02 f:requiredMaxRaValue ?lim . ?r f:surfaceRoughnessRaValue ?v . BIND("top Ra" AS ?char) }
  BIND((?lim - ?v) / ?lim AS ?m)
 } GROUP BY ?ps }

  ?e f:evaluatesSetting ?ps ; f:forRequirement f:Req02 ; f:coversAssessment ?a .
  ?a f:assessesResult ?r .
  ?specimen f:hasResult ?r .
  { f:Req02 f:requiredMaxLengthDeviation ?lim . ?r f:absLengthDeviationValue ?v . BIND("length" AS ?char) }
  UNION { f:Req02 f:requiredMaxWidthDeviation ?lim . ?r f:absWidthDeviationValue ?v . BIND("width" AS ?char) }
  UNION { f:Req02 f:requiredMaxHeightDeviation ?lim . ?r f:absHeightDeviationValue ?v . BIND("height" AS ?char) }
  UNION { f:Req02 f:requiredMaxRaValue ?lim . ?r f:surfaceRoughnessRaValue ?v . BIND("top Ra" AS ?char) }
  BIND((?lim - ?v) / ?lim AS ?m)

 BIND(?v AS ?value) BIND(?lim AS ?limit)
 FILTER(?m = ?worstMargin)
} ORDER BY DESC(?worstMargin) ?ps ?specimen

